#from __future__ import annotations # Pour le pc d'Arthur
import numpy as np
from .priceseries import PriceSeries


class Asset:
    """
    Représente un actif financier avec son historique de prix.
    Pattern de conception : COMPOSITION
    Asset POSSÈDE une PriceSeries (relation HAS-A, pas IS-A).
    ───────────────────────────────────
    Attributes:
        ticker: Symbole (ex: 'AAPL')
        ps: Instance PriceSeries contenant l'historique
        sector: Classification sectorielle optionnelle
        currency: Devise des prix (défaut: USD)
    """
    
    def __init__(
        self, 
        ticker: str, 
        ps: PriceSeries,
    ) -> None:
        # Validation des entrées dans le constructeur
        if not ticker or not ticker.strip():
            raise ValueError("Le ticker ne peut pas être vide")
        if any(p < 0 for p in ps.prix):
            raise ValueError("La série de prix ne peut pas contenir de valeurs négatives")
        
        self.ticker = ticker
        self.ps = ps  # Composition : Asset POSSÈDE une PriceSeries
        self.monte_carlo_result = None # Attribut pour stocker le résultat du Monte Carlo, initialisé à None
    
    def __repr__(self) -> str:
        """Représentation pour le développement."""
        return f"Asset({self.ticker!r}, {len(self.ps)} ps)"
    
    def __str__(self) -> str:
        """Représentation pour l'utilisateur."""
        return f"{self.ticker}: ${self.current_price:.2f}"
    

    @property
    def current_price(self) -> float:
        """Dernier prix connu."""
        return self.ps.prix[-1]
    
    @property
    def total_return(self) -> float:
        """Rendement total (délègue à PriceSeries)."""
        return self.ps.total_return()
    
    @property
    def mean_daily_return(self)-> float:
        """Rendement moyen journalier (délègue à PriceSeries)."""
        return self.ps.mean_daily_return()
    
    @property 
    def annualized_return(self)->float:
        """Rendement annualisé (délègue à PriceSeries)."""
        return self.ps.annualized_return()

    @property
    def daily_volatility(self) ->float:
        """Volatilité journalière (délègue à PriceSeries)."""
        return self.ps.daily_volatility()

    @property
    def annualized_volatility(self) -> float:
        """Volatilité annualisée (délègue à PriceSeries)."""
        return self.ps.annualized_volatility()
    
    @property
    def sharpe_ratio(self) -> float:
        """Ratio de Sharpe (délègue à PriceSeries)."""
        return self.ps.sharpe_ratio()
    
    @property
    def max_drawdown(self) -> float:
        """Drawdown maximum (délègue à PriceSeries)."""
        return self.ps.max_drawdown()
    
    @property
    def base100(self) -> list[float]:
        """Base 100 (délègue à PriceSeries)."""
        return self.ps.base100()
    
    
    def correlation_with(self, other: "Asset") -> float:
        """
        Calcule la corrélation de Pearson des log-rendements avec un autre actif.
        
        Args:
            other: Un autre Asset
        
        Returns:
            Coefficient de corrélation entre -1 et 1
        """
        # Gestion des tailles trop faibles 
        if len(self.ps.prix) < self.ps.nombre_min_annualisation or len(other.ps.prix) < other.ps.nombre_min_annualisation:
            return np.nan
        

        # Récupération des log-rendements
        x = self.ps.all_log_return()
        y = other.ps.all_log_return()

        n = min(len(x), len(y))
        
        # Alignement des longueurs (gestion des séries de tailles différentes)
        x = x[:n]
        y = y[:n]
        
        # On calcul la moyenne
        mean_x = sum(x)/n
        mean_y = sum(y)/n

        # Centrage des valeurs
        cx = [x_i - mean_x for x_i in x]
        cy = [y_i - mean_y for y_i in y]

        # Covariance (numérateur)
        covariance = sum(c_x * c_y for c_x, c_y in zip(cx, cy)) / (n - 1)
        
        # Variances pour le dénominateur
        var_x = sum(c_x * c_x for c_x in cx) / (n - 1)
        var_y = sum(c_y * c_y for c_y in cy) / (n - 1)
        
        # Vérification de la variance nulle
        if var_x == 0 or var_y == 0:
            return np.nan
        
        return covariance / np.sqrt(var_x * var_y)
    
